select cik, concept, period_end, val from {{ ref('stg_facts') }}
where duration_days is null and val >= 0 and concept in ('Assets','CashAndCashEquivalentsAtCarryingValue','LongTermDebt','LongTermDebtNoncurrent','LongTermDebtCurrent','DebtInstrumentCarryingAmount','DebtAndCapitalLeaseObligations','SecuredDebt','UnsecuredDebt','SeniorNotes','LineOfCredit','NotesPayable','NotesAndLoansPayable','LongTermDebtAndCapitalLeaseObligations','LongTermDebtAndCapitalLeaseObligationsIncludingCurrentMaturities')
